/**
 * Client-side slug preview. The authoritative slug is generated by the backend
 * on save (`generateSlug` appends a short uuid), so this is display-only.
 */
export function slugify(value: string): string {
  return value
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9\s-]/g, "")
    .replace(/\s+/g, "-")
    .replace(/-+/g, "-");
}
